mapper.select:
select event_id as eventId, field_name as fieldName, value from cm_event_localized_fields where event_id in
#{eid}
and status = 'ready' and trim(value) != '' and field_name in ('title','summary','venue','address','format','audience','curator_note') order by event_id, field_name, case locale when #{locale} then 0 when 'zh' then 1 when 'en' then 2 else 3 end

select event_id as eventId, language_code as languageCode from cm_event_language_codes where event_id in
#{eid}
order by event_id, language_code

select event_id as eventId, focus_order as sortOrder, value from cm_event_relationship_focuses where event_id in
#{eid}
and status = 'ready' and trim(value) != '' order by event_id, focus_order, case locale when #{locale} then 0 when 'zh' then 1 when 'en' then 2 else 3 end

select event_id as eventId, status, count(1) as cnt from cm_event_registrations where event_id in
#{eid}
group by event_id, status
